package management

import "net/http"

func (s *Server) static(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/admin/":
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write([]byte(adminHTML))
	case "/admin/app.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		w.Write([]byte(adminJS))
	case "/admin/style.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write([]byte(adminCSS))
	default:
		http.NotFound(w, r)
	}
}

const adminHTML = `<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Code Marketplace Yönetim</title><link rel="stylesheet" href="/admin/style.css"><script src="/admin/app.js" defer></script></head>
<body><header><a href="/admin/" class="brand">code-marketplace<span>Yönetim</span></a><div id="identity"></div><button id="logout" hidden>Çıkış</button></header>
<main><p id="notice" role="status" aria-live="polite" hidden></p>
<section id="login"><p class="eyebrow">KURUMSAL ERİŞİM</p><h1>Marketplace yönetimi</h1><p class="muted">Active Directory hesabınızla giriş yapın.</p><form id="login-form"><label>Kullanıcı adı<input name="username" autocomplete="username" maxlength="256" required></label><label>Parola<input name="password" type="password" autocomplete="current-password" maxlength="4096" required></label><button type="submit" class="primary">Giriş yap</button></form><p class="muted small">Erişim, yetkili AD gruplarıyla sınırlandırılmıştır.</p></section>
<div id="dashboard" hidden><div class="heading"><div><p class="eyebrow">OFFLINE KATALOG</p><h1>Eklentiler ve kabul politikası</h1></div><button id="refresh">Yenile</button></div>
<div class="stats"><section><span class="muted">Yayımlanan sürüm</span><strong id="count">0</strong></section><section><span class="muted">Publisher politikası</span><strong id="mode"></strong></section><section><span class="muted">Kabul koşulları</span><strong class="small">İmza + sandbox onayı</strong></section></div>
<section class="panel"><div class="section-title"><h2>Katalog</h2><input id="search" type="search" placeholder="Eklenti veya yayıncı ara" aria-label="Katalogda ara"></div><div class="table-wrap"><table><thead><tr><th>Eklenti</th><th>Sürüm / platform</th><th>Kabul kaydı</th><th>İşlem</th></tr></thead><tbody id="catalog"></tbody></table></div><p id="empty" class="muted" hidden>Henüz yayımlanmış eklenti yok.</p></section>
<div class="columns"><section class="panel" id="upload-panel" hidden><h2>Eklenti yükle</h2><p class="muted">Dosyalar incoming klasörüne aktarılır. Sandbox ve importer kontrolleri tamamlandığında yayımlanır.</p><form id="upload-form"><label>VSIX<input type="file" name="vsix" accept=".vsix" required></label><label>Microsoft imzası<input type="file" name="signature" accept=".sigzip" required></label><label>Publisher raporu<input type="file" name="publisherReport" accept=".json"></label><label>Sandbox raporu (isteğe bağlı)<input type="file" name="sandboxReport" accept=".json"></label><button type="submit" class="primary">Taramaya gönder</button></form></section>
<section class="panel"><h2>Publisher politikası</h2><p id="policy-detail" class="muted"></p><ul id="allowlist"></ul><p class="muted small">Politika ve bağlantı ayarları YAML ile yönetilir. Mevcut paketler politika değişince otomatik kaldırılmaz.</p></section></div>
<section class="panel"><div class="section-title"><h2>Son import sonuçları</h2><span id="import-time" class="muted small"></span></div><div class="table-wrap"><table><thead><tr><th>Dosya</th><th>Durum</th><th>Açıklama</th></tr></thead><tbody id="imports"></tbody></table></div></section></div>
<footer>Code Marketplace · AGPL-3.0 · Coder temel alınarak geliştirilmiştir.</footer></main></body></html>`

const adminCSS = `:root{color-scheme:light;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#18352c;background:#f3f6f4}*{box-sizing:border-box}body{margin:0}header{display:flex;gap:20px;align-items:center;padding:22px 5%;border-bottom:1px solid #dbe4df;background:#fff}.brand{text-decoration:none;font-size:20px;font-weight:750;color:#18352c;letter-spacing:-.5px}.brand span{font-size:12px;letter-spacing:.1em;text-transform:uppercase;margin-left:16px;color:#647c71}#identity{margin-left:auto;font-size:14px}main{max-width:1240px;margin:auto;padding:40px 28px}h1{font-size:32px;letter-spacing:-1px;margin:8px 0 14px}h2{font-size:18px;margin:0 0 18px}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.16em;color:#397459}.muted{color:#62766b;line-height:1.65}.small{font-size:13px}.heading,.section-title{display:flex;justify-content:space-between;align-items:center;gap:20px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:24px 0}.stats section,.panel{background:#fff;border:1px solid #dbe4df;border-radius:12px;padding:24px}.stats strong{display:block;font-size:28px;margin-top:12px}.stats strong.small{font-size:17px;padding-top:8px}.panel{margin-bottom:20px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}th{color:#62766b;font-size:11px;text-transform:uppercase;letter-spacing:.08em;padding:12px 8px;border-bottom:1px solid #dbe4df}td{padding:18px 8px;border-bottom:1px solid #edf1ee;vertical-align:top;max-width:400px;overflow-wrap:anywhere}td span{display:block;margin-top:5px;font-size:12px;color:#62766b}button{background:#fff;border:1px solid #bdcfc3;border-radius:6px;padding:10px 16px;color:#214a36;font-weight:650;cursor:pointer}button:hover{background:#eef5f0}button:disabled{opacity:.5;cursor:wait}.primary{background:#23583f;color:#fff;border-color:#23583f}.primary:hover{background:#19452f}.danger{font-size:12px;color:#96372f;border-color:#e7cdc9;padding:8px 10px}label{display:block;font-size:13px;font-weight:600;margin:18px 0}input{display:block;width:100%;padding:11px;border:1px solid #bdcfc3;border-radius:6px;margin-top:8px;background:#fff;color:#18352c;font:inherit}input:focus,button:focus-visible{outline:2px solid #498465;outline-offset:2px}input[type=file]{font-size:12px}#search{max-width:280px;margin:0;font-size:13px}#login{max-width:430px;margin:5vh auto;background:#fff;border:1px solid #dbe4df;border-radius:14px;padding:36px}#login-form button{width:100%;margin-top:6px}#notice{padding:14px 18px;background:#e0f0e5;border:1px solid #b8d7c2;border-radius:8px;margin:0 0 24px}#notice.error{background:#fff0ee;border-color:#e7c5c0;color:#8e342c}.badge{display:inline-block;padding:5px 9px;background:#edf5ef;color:#23583f;border-radius:5px;font-size:12px}li{font-size:14px;margin:9px 0}footer{padding:24px 0;color:#708276;font-size:12px}[hidden]{display:none!important}@media(max-width:760px){main{padding:24px 16px}.stats,.columns{grid-template-columns:1fr}.heading,.section-title{align-items:flex-start;flex-direction:column}h1{font-size:26px}.brand span{display:none}header{padding:18px}#search{max-width:100%}.panel{padding:18px}}`

const adminJS = `"use strict";
const el=id=>document.getElementById(id);
let session=null,entries=[];
const notice=(message,error=false)=>{el("notice").textContent=message;el("notice").className=error?"error":"";el("notice").hidden=false};
async function request(path,options={}){const headers={...options.headers};if(session)headers["X-CSRF-Token"]=session.csrfToken;if(options.body&&!(options.body instanceof FormData))headers["Content-Type"]="application/json";const response=await fetch("/admin/api/"+path,{...options,headers,credentials:"same-origin",cache:"no-store"});if(response.status===204)return null;const data=await response.json();if(!response.ok){if(response.status===401){session=null;showLogin()}throw new Error(data.error||"İşlem başarısız")}return data}
function showLogin(){el("login").hidden=false;el("dashboard").hidden=true;el("logout").hidden=true;el("identity").textContent=""}
function showDashboard(){el("login").hidden=true;el("dashboard").hidden=false;el("logout").hidden=false;el("identity").textContent=session.user.name+" · "+(session.user.role==="admin"?"Yönetici":"Görüntüleme");el("upload-panel").hidden=session.user.role!=="admin"}
function cell(row,text){const td=document.createElement("td");td.textContent=text;row.append(td);return td}
function renderCatalog(){const tbody=el("catalog");tbody.replaceChildren();const search=el("search").value.toLocaleLowerCase();for(const entry of entries){if(!(entry.publisher+"."+entry.extension+" "+entry.displayName).toLocaleLowerCase().includes(search))continue;const row=document.createElement("tr");const identity=cell(row,entry.displayName||entry.extension);const name=document.createElement("span");name.textContent=entry.publisher+"."+entry.extension;identity.append(name);cell(row,entry.version.version+" / "+(entry.version.targetPlatform||"universal"));cell(row,entry.receipt?"Sandbox onaylı"+(entry.receipt.publisher?.publisher?.isDomainVerified?" · Verified":""):"Eski kayıt, kabul belgesi yok");const action=cell(row,"");if(session.user.role==="admin"){const button=document.createElement("button");button.textContent="Yayından kaldır";button.className="danger";button.addEventListener("click",async()=>{const reason=window.prompt(entry.publisher+"."+entry.extension+" "+entry.version.version+" sürümünü kaldırma gerekçesi:");if(!reason?.trim())return;button.disabled=true;try{await request("revoke",{method:"POST",body:JSON.stringify({publisher:entry.publisher,extension:entry.extension,version:entry.version,reason})});notice("Sürüm yayından kaldırıldı. Otomatik import bu sürümü yeniden yayımlamayacak.");await refresh()}catch(error){notice(error.message,true)}finally{button.disabled=false}});action.append(button)}tbody.append(row)}el("count").textContent=entries.length;el("empty").hidden=tbody.children.length>0}
async function refresh(){const [catalog,policy,imports]=await Promise.all([request("catalog"),request("policy"),request("imports")]);entries=catalog.entries;renderCatalog();el("mode").textContent=policy.mode;el("policy-detail").textContent="Publisher raporu azami yaşı: "+policy.maxAge+". İzin listesi:";el("allowlist").replaceChildren();for(const name of policy.allowedPublishers.length?policy.allowedPublishers:[policy.mode==="verified"?"Tüm verified yayıncılar":policy.mode==="any"?"Publisher filtresi kapalı":"İzin verilen yayıncı yok"]){const li=document.createElement("li");li.textContent=name;el("allowlist").append(li)}el("upload-form").elements.publisherReport.required=policy.mode!=="any";el("import-time").textContent=imports.completedAt?new Date(imports.completedAt).toLocaleString():"Henüz import çalışmadı";el("imports").replaceChildren();for(const result of imports.results){const row=document.createElement("tr");cell(row,result.file);const td=cell(row,"");const badge=document.createElement("span");badge.className="badge";badge.textContent=result.status;td.append(badge);cell(row,[result.reason,result.missingDependencies?.length?"Eksik bağımlılık: "+result.missingDependencies.join(", "):""].filter(Boolean).join(" · "));el("imports").append(row)}}
el("login-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button");button.disabled=true;try{session=await request("login",{method:"POST",body:JSON.stringify({username:form.elements.username.value,password:form.elements.password.value})});form.elements.password.value="";el("notice").hidden=true;showDashboard();await refresh()}catch(error){form.elements.password.value="";notice(error.message,true)}finally{button.disabled=false}});
el("logout").addEventListener("click",async()=>{try{await request("logout",{method:"POST",body:"{}"});session=null;showLogin()}catch(error){notice(error.message,true)}});
el("refresh").addEventListener("click",()=>refresh().catch(error=>notice(error.message,true)));
el("search").addEventListener("input",renderCatalog);
el("upload-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button"),data=new FormData();for(const name of ["vsix","signature","publisherReport","sandboxReport"]){const file=form.elements[name].files[0];if(file)data.append(name,file)}button.disabled=true;notice("Dosyalar aktarılıyor...");try{const result=await request("uploads",{method:"POST",body:data});form.reset();notice(result.file+" incoming klasörüne aktarıldı. Tarama ve import bekleniyor.")}catch(error){notice(error.message,true)}finally{button.disabled=false}});
request("session").then(async data=>{session=data;showDashboard();await refresh()}).catch(()=>showLogin());`
